entries[63247] = { ["name"] = "Lebendiger Tsunami", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nIhr beschwört einen lebendigen Tsunami, der bei Kontakt mit feindlichen Zielen 6013 bis 6987 Naturschaden verursacht sowie 10 Sek. lang alle 2 Sek. 1850 bis 2150 Naturschaden." }
