entries[63272] = { ["name"] = "Hurrikan", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nErzeugt einen wütenden Sturm im Zielgebiet, der allen in der Nähe befindlichen Feinden alle 2 Sek. 7863 bis 9137 Naturschaden zufügt und die Zeit zwischen Angriffen betroffener Feinde um 67% erhöht. Hält 10 Sek. lang an. Muss kanalisiert werden, um den Zauber aufrechtzuerhalten." }
