entries[63277] = { ["name"] = "Schattengeschoss", ["text"] = "Unbegrenzte Reichweite\nSofort\nFeuert ein Schattengeschoss auf ein Ziel ab, verursacht 11310 bis 12690 Schattenschaden an allen Feinden nahe dem Einschlagsort und stößt sie zurück. Hinterlässt nach dem Einschlag ein Energiefeld, das 20 Sek. lang verbleibt. Dieses Feld erhöht den verursachten Magieschaden um bis zu 100%, erhöht das Zaubertempo um 100%, verringert die verursachte Heilung um 75% und verringert die Manakosten von Zauberwirkern um 75%." }
