entries[63458] = { ["name"] = "Fallenbeherrschung", ["text"] = "Verringert die Abklingzeit aller Fallen sowie Eurer Fähigkeit 'Schwarzer Pfeil' um 6 Sek. und gewährt allen Fallen verschiedene Boni:\n\nFrostfalle und Eiskältefalle - Erhöht die Dauer um 30%.\n\nSprengfalle und 'Schwarzer Pfeil' - Erhöht den regelmäßigen Schaden um 30%.\n\nSchlangenfalle - Erhöht die Anzahl der beschworenen Schlangen um 4." }
