entries[63468] = { ["name"] = "Durchschlagende Schüsse", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie kritischen Treffer Eurer Fähigkeiten 'Gezielter Schuss', 'Zuverlässiger Schuss' und 'Schimärenschuss' lassen das Ziel im Verlauf von 8 Sek. für 30% des verursachten Schadens bluten." }
