entries[63472] = { ["name"] = "Flammenstrahlen", ["text"] = "Wirken in 2.7 sek.\nStampft auf den Boden, wodurch sich Flammengeysire unter allen Feinden öffnen. Diese Geysire verursachen 8483 bis 9517 Feuerschaden, schleudern die Ziele in die Luft und unterbrechen 8 Sek. lang alle gewirkten Zauber. Zusätzlich erleiden die Ziele 8 Sek. lang 2000 Feuerschaden pro Sekunde." }
entries[63473] = { ["name"] = "Versengen", ["text"] = "Sofort\nFeuert einen Flammenstrahl ab, der alle Gegner innerhalb von 30 Metern vor dem Zaubernden verbrennt und 3 Sek. lang alle 0,5 Sek. 3770 bis 4230 Feuerschaden verursacht. Zusätzlich erhitzt sich der Boden und fängt Feuer, wodurch alle Feinde innerhalb von 13 Metern pro Sekunde 3016 bis 3384 Feuerschaden erleiden. Eisenkonstrukte innerhalb dieses Bereichs werden sich aufheizen und letztendlich schmelzen." }
entries[63474] = { ["name"] = "Versengen", ["text"] = "Kanalisiert (Wirken in 3 sek.) 5 sek. Abklingzeit\nFeuert einen Flammenstrahl ab, der alle Gegner innerhalb von 30 Metern vor dem Zaubernden verbrennt und 3 Sek. lang alle 0,5 Sek. 3770 bis 4230 Feuerschaden verursacht. Zusätzlich erhitzt sich der Boden und fängt Feuer, wodurch alle Feinde innerhalb von 13 Metern pro Sekunde 3016 bis 3384 Feuerschaden erleiden. Eisenkonstrukte innerhalb dieses Bereichs werden sich aufheizen und letztendlich schmelzen." }
