entries[63479] = { ["name"] = "Kettenblitzschlag", ["text"] = "500 Mana Unbegrenzte Reichweite\nWirken in 2 sek.\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 5 Ziele aus und verursacht bei jedem Naturschaden." }
entries[63480] = { ["name"] = "Überladung", ["text"] = "Sofort\nFokussiert die gesamte Energie des Zaubernden in eine einzige Blitzkugel. Die Kugel wächst 6 Sek. lang an, bis sie letztendlich explodiert, an allen Feinden innerhalb von 20 Metern 25000 Naturschaden verursacht und sie zu Boden stößt." }
