entries[63489] = { ["name"] = "Runenschild", ["text"] = "Wirken in 1.5 sek.\nBedeckt den Zaubernden mit magischen Runen, die bis zu 50000 Schaden absorbieren. Sobald 50000 Schaden absorbiert wurde, wird dieser in eine mächtige Energieexplosion umgewandet, die den Schaden des Zaubernden 15 Sek. lang um 50% erhöht." }
