entries[63535] = { ["name"] = "Packen", ["text"] = "90 Meter Reichweite\nSofort 5 sek. Abklingzeit\nStürmt ein zufälliges feindliches Ziel an, ergreift es und wirft es in den Schlackentopf. Das Ziel kann den Zaubernden nicht angreifen und erleidet 10 Sek. lang pro Sekunde 0 Feuerschaden. Wenn das Ziel überlebt, wird es von der magischen Schlacke gestärkt, die 10 Sek. lang das Bewegungstempo um 100% und das Tempo um 100% erhöht." }
entries[63536] = { ["name"] = "Schlackenverstärkung", ["text"] = "Unbegrenzte Reichweite\nSofort\nStürmt ein zufälliges feindliches Ziel an, ergreift es und wirft es in den Schlackentopf. Das Ziel kann den Zaubernden nicht angreifen und erleidet 10 Sek. lang pro Sekunde 0 Feuerschaden. Wenn das Ziel überlebt, wird es von der magischen Schlacke gestärkt, die 10 Sek. lang das Tempo um 100% erhöht." }
