entries[63541] = { ["name"] = "Gabelblitzschlag", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 2 sek.\nFügt Gegnern in einem kegelförmigen Bereich vor dem Zaubernden Naturschaden zu." }
entries[63544] = { ["name"] = "Rapide Erneuerung", ["text"] = "Unbegrenzte Reichweite\nSofort\nEuer Zauber 'Erneuerung' heilt das Ziel sofort um einen Teil seines gesamten regelmäßigen Effektes." }
