entries[63546] = { ["name"] = "Stampfen", ["text"] = "10 Meter Reichweite\nSofort\nStampft auf den Boden und verursacht an nahen Gegnern normalen Schaden." }
entries[63547] = { ["name"] = "Gewalttätige Erde", ["text"] = "60 Meter Reichweite\nWirken in 1.5 sek.\nDie gewalttätige Erde reißt unter den Füßen der Ziele auf und schleudert sie nach oben. Fügt allen innerhalb von 4 Metern um das Ziel 12950 bis 15050 Naturschaden zu." }
entries[63548] = { ["name"] = "Bodenriss", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Erde bricht auf und verursacht 6 Sek. lang alle 1 Sek. Schaden." }
entries[63549] = { ["name"] = "Gelenke versteinern", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht Naturschaden und verringert 20 Sek. lang das Bewegungstempo um 25%." }
entries[63550] = { ["name"] = "Wächterpeitsche", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nVerursacht 16650 bis 19350 Naturschaden und 6 Sek. lang zusätzlich alle 1 Sek. 5088 bis 5912 Naturschaden." }
entries[63551] = { ["name"] = "Giftatem", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 9250 bis 10750 Naturschaden zu sowie 12 Sek. lang alle 2 Sek. zusätzlich 6013 bis 6987 Naturschaden." }
entries[63552] = { ["name"] = "Dornenschwarm", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt Feinden innerhalb von 6 Metern um das Ziel 9250 bis 10750 Naturschaden zu." }
entries[63553] = { ["name"] = "Eisenwurzeldornen", ["text"] = "40 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 1050 Naturschaden zufügen. Hält 10 Sek. lang an." }
entries[63554] = { ["name"] = "Gelassenheit", ["text"] = "200 Mana\nKanalisiert (Wirken in 10 sek.)\nRegeneriert alle in der Nähe befindlichen Gruppenmitglieder 10 Sek. lang alle 2 Sek. um 27750 bis 32250. Kanalisiert." }
entries[63555] = { ["name"] = "Explosives Shredding: Shredder Return Kill Credit" }
entries[63556] = { ["name"] = "Pflege", ["text"] = "22% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein befreundetes Ziel um 46250 bis 53750. Ist ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen' oder 'Blühendes Leben' auf dem Ziel aktiv, erhöht sich die Heilung um zusätzliche 20%." }
entries[63557] = { ["name"] = "Hurrikan", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nErzeugt einen wütenden Sturm im Zielgebiet, der allen in der Nähe befindlichen Feinden alle 2 Sek. 7400 bis 8600 Naturschaden zufügt und die Zeit zwischen Angriffen betroffener Feinde um 67% erhöht. Hält 10 Sek. lang an. Muss kanalisiert werden, um den Zauber aufrechtzuerhalten." }
entries[63558] = { ["name"] = "Fel Fire Cosmetic" }
entries[63559] = { ["name"] = "Leben binden", ["text"] = "45 Meter Reichweite\nWirken in 1.5 sek.\nHeilt 6 Sek. lang alle 1 Sek. um 13875 bis 16125." }
entries[63560] = { ["name"] = "Dunkle Transformation", ["text"] = "1 Unheilige Rune / -10 Runenmacht 100 Meter Reichweite\nSpontanzauber\nZehrt 5 Aufladungen von 'Schattenmacht' auf Eurem Ghul auf und verwandelt ihn 30 Sek. lang in eine mächtige untote Monstrosität. Die Angriffe des Ghuls werden dadurch machtvoller und werden durch neue Funktionen ersetzt, solang die Transformation anhält." }
entries[63562] = { ["name"] = "Frostspeer", ["text"] = "60 Meter Reichweite\nSofort\nDer Frostspeer verlangsamt das Angriff- und Zaubertempo um 100%, verursacht 7863 bis 9137 Frostschaden sowie zusätzlich bis Abbruch lang alle 5 100 Frostschaden." }
entries[63563] = { ["name"] = "Frostbiss", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Frostspeer verlangsamt das Angriff- und Zaubertempo um 100%, verursacht 7863 bis 9137 Frostschaden sowie zusätzlich 5 Sek. lang alle 1 3145 bis 3655 Frostschaden." }
entries[63564] = { ["name"] = "Umarmung des Winters", ["text"] = "60 Meter Reichweite\nSofort\nEin gefrorener Schild, der Schaden absorbiert und den verursachten körperlichen Schaden um 100% erhöht. Hält 1 Min. lang an." }
entries[63565] = { ["name"] = "Teufelsfeuer enziehen", ["text"] = "10 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nEntzieht einem Teufelsfeuerfeld am Dämonenhügel das Teufelsfeuer." }
